"""Candidate generation for the synthetic peptide mass matching report."""

_RESIDUE_MASSES = {
    "A": 71,
    "C": 103,
    "D": 115,
    "E": 129,
    "K": 128,
    "P": 97,
    "R": 156,
}


def _cleavage_segments(sequence):
    """Return zero-based inclusive segment ranges for one digested sequence."""
    n = len(sequence)
    cuts = [n - 1]  # Always cut at the end.
    for i in range(n - 1):
        if sequence[i] in "KR" and sequence[i + 1] != "P":
            cuts.append(i)
    cuts = sorted(set(cuts))

    segments = []
    previous = -1
    for cut in cuts:
        segments.append((previous + 1, cut))
        previous = cut
    return segments


def _emitted_ranges(sequence):
    """Elementary segments and joined adjacent pairs, zero-based inclusive."""
    segments = _cleavage_segments(sequence)
    ranges = []
    for start, end in segments:
        if end - start + 1 >= 2:
            ranges.append((start, end))
    for left_index in range(len(segments) - 1):
        start = segments[left_index][0]
        end = segments[left_index + 1][1]
        if end - start + 1 >= 2:
            ranges.append((start, end))
    return ranges


def _fragment_ions(masses):
    """All prefix and suffix sums of length 1..n-1, preserving multiplicity."""
    n = len(masses)
    ions = []
    for length in range(1, n):
        ions.append(sum(masses[:length]))
    for length in range(1, n):
        ions.append(sum(masses[n - length:]))
    return ions


def candidate_fragments(proteins, modifications):
    """Yield (candidate_id, kind, ions) for every distinct candidate."""
    for protein in proteins:
        protein_id = protein["id"]
        sequence = protein["sequence"]
        for kind, digest_sequence in (
            ("target", sequence),
            ("decoy", sequence[::-1]),
        ):
            for start, end in _emitted_ranges(digest_sequence):
                span = digest_sequence[start:end + 1]
                base_id = (
                    f"{protein_id}/{kind}:{start + 1}-{end + 1}:none"
                )
                base_masses = [_RESIDUE_MASSES[residue] for residue in span]
                yield (base_id, kind, _fragment_ions(base_masses))

                for modification in modifications:
                    for position in range(start, end + 1):
                        if digest_sequence[position] != modification["residue"]:
                            continue
                        candidate_id = (
                            f"{protein_id}/{kind}:{start + 1}-{end + 1}:"
                            f"{modification['name']}@{position + 1}"
                        )
                        masses = base_masses[:]
                        masses[position - start] += modification["shift"]
                        yield (candidate_id, kind, _fragment_ions(masses))

from runtime import build, read

from engines.analysis.candidate_fragments import candidate_fragments
from engines.analysis.peak_matching import match_score


def _selection_key(candidate_id, kind, score):
    """Order candidates from best to worst for a single spectrum."""
    return (
        -score[0],
        -score[1],
        -score[2],
        0 if kind == "target" else 1,
        candidate_id,
    )


def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    request = payload["request"]
    proteins = request["proteins"]
    modifications = request["modifications"]
    spectra = request["spectra"]
    tolerance = request["tolerance"]

    candidates = list(candidate_fragments(proteins, modifications))

    winners = []
    for spectrum in spectra:
        spectrum_id = spectrum["id"]
        peaks = spectrum["peaks"]
        best_candidate = None
        best_key = None
        for candidate_id, kind, ions in candidates:
            score = match_score(ions, peaks, tolerance)
            key = _selection_key(candidate_id, kind, score)
            if best_key is None or key < best_key:
                best_key = key
                best_candidate = (candidate_id, kind, score)
        candidate_id, kind, score = best_candidate
        winners.append(
            {
                "spectrum": spectrum_id,
                "candidate": candidate_id,
                "kind": kind,
                "score": [score[0], score[1], score[2]],
            }
        )

    winners.sort(key=lambda winner: (
        -winner["score"][0],
        -winner["score"][1],
        -winner["score"][2],
        winner["spectrum"],
    ))

    decoys_so_far = 0
    targets_so_far = 0
    for winner in winners:
        if winner["kind"] == "decoy":
            decoys_so_far += 1
        else:
            targets_so_far += 1
        winner["fdr_numerator"] = decoys_so_far
        winner["fdr_denominator"] = max(1, targets_so_far)

    return {"candidate_count": len(candidates), "winners": winners}


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)

